-- 5. Directly Update dbo.AttendanceLogs with 100% Clean Data
PRINT '>>> Directly Updating dbo.AttendanceLogs (Purifying Weekly Offs & Applying Shifts)...';

;WITH DedupedMaster AS (
    SELECT 
        emp.EmployeeId,
        m.AttendanceDate,
        m.ShiftIdResolved,
        m.InTime,
        m.OutTime,
        m.Duration,
        m.Status,
        m.StatusCode,
        m.P1Status,
        m.Present,
        m.Absent,
        m.WeeklyOff,
        m.Holiday,
        m.LateBy,
        m.OverTime,
        ROW_NUMBER() OVER (PARTITION BY emp.EmployeeId, m.AttendanceDate ORDER BY m.Id) AS rn
    FROM #CleanSereneMaster m
    CROSS APPLY (
        SELECT TOP 1 e.EmployeeId 
        FROM dbo.Employees e 
        WHERE LTRIM(RTRIM(CAST(e.EmployeeCode AS VARCHAR(50)))) = m.EmployeeCode 
           OR (m.EmployeeCode IN ('31015', '31034') AND (e.EmployeeCode IN ('31015', '31034') OR UPPER(e.EmployeeName) LIKE '%PRASHAN%'))
           OR (m.EmployeeCode IN ('31109', '31104') AND (e.EmployeeCode IN ('31109', '31104') OR UPPER(e.EmployeeName) LIKE '%AMIT%BISWAL%'))
           OR (m.EmployeeCode IN ('31013', '31015') AND (e.EmployeeCode IN ('31013') OR UPPER(e.EmployeeName) LIKE '%CHANDRAPPA%'))
           OR (m.EmployeeCode = '31109-HK' AND UPPER(e.EmployeeName) LIKE '%PARVATHI%')
           OR (m.EmployeeCode IN ('32085', '32086') AND UPPER(e.EmployeeName) LIKE '%MRITYUNJAY%')
           OR (m.EmployeeCode IN ('22082', '7') AND UPPER(e.EmployeeName) LIKE '%KHAKENDRA%')
        ORDER BY e.EmployeeId
    ) emp
)
UPDATE a
SET 
    a.ShiftId = u.ShiftIdResolved,
    a.InTime = ISNULL(u.InTime, '1900-01-01 00:00:00'),
    a.OutTime = ISNULL(u.OutTime, '1900-01-01 00:00:00'),
    a.Duration = u.Duration,
    a.Status = u.Status,
    a.StatusCode = u.StatusCode,
    a.P1Status = u.P1Status,
    a.Present = u.Present,
    a.Absent = u.Absent,
    a.WeeklyOff = u.WeeklyOff,
    a.Holiday = u.Holiday,
    a.LateBy = u.LateBy,
    a.EarlyBy = 0,
    a.OverTime = u.OverTime,
    a.OverTimeE = 0,
    a.LeaveDuration = 0,
    a.LossOfHours = 0,
    a.SpecialOffDuration = 0,
    a.MissedInPunch = 0,
    a.IsonSpecialOff = 0,
    a.MissedOutPunch = 0,
    a.Remarks = 'Excel Verified Serene'
FROM dbo.AttendanceLogs a
JOIN DedupedMaster u 
  ON a.EmployeeId = u.EmployeeId AND CAST(a.AttendanceDate AS DATE) = u.AttendanceDate
WHERE u.rn = 1;

PRINT '    [OK] Updated ' + CAST(@@ROWCOUNT AS VARCHAR(10)) + ' records in dbo.AttendanceLogs.';
PRINT '';

